export type GoogleIconName = keyof typeof PATHS;

export interface GoogleIconProps extends Omit<SVGProps<SVGSVGElement>, 'name'> {
  name: GoogleIconName;
  size?: number;
}

export function GIcon({ name, size, className, style, ...rest }: GoogleIconProps) {
  // A single optical scale keeps every icon crisp and comfortably sized –
  // MUI icon buttons read best a step above the text they sit next to.
  const px = size ? Math.round(size * 1.12) : undefined;
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 -960 960 960"
      fill="currentColor"
      width={px}
      height={px}
      className={clsx(!size && 'size-[1.25rem]', 'shrink-0 select-none', className)}
      style={style}
      aria-hidden="true"
      focusable="false"
      {...rest}
    >
      <path d={PATHS[name]} />
    </svg>
  );
}
